1	// The Action-side GitHub reader for the scheduler (per-project-scheduling
2	// DESIGN §10: engine/scheduler/ is the one place that legitimately uses the
3	// Action's GITHUB_TOKEN — everything session-side stays MCP-only). A minimal
4	// REST client over global fetch: `gh(path) -> { status, json }`, the same shape
5	// the fleet planner's injected reader uses, so the collectors read uniformly and
6	// test against a fake `gh`.
7	//
8	// `path` is an API path beginning with `/` (e.g. `/repos/owner/name/commits`);
9	// the base URL and auth are applied here. A non-2xx returns `{ status, json:
10	// null }` rather than throwing, so a 404 (no release yet, missing file) is data,
11	// not an error.
12	
13	const API = process.env.GITHUB_API_URL || 'https://api.github.com';
14	
15	export function makeGh({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
16	  // `gh(path)` reads; `gh(path, { method, body })` writes (body JSON-encoded).
17	  return async function gh(path, { method = 'GET', body } = {}) {
18	    const res = await fetchImpl(`${api}${path}`, {
19	      method,
20	      headers: {
21	        accept: 'application/vnd.github+json',
22	        'x-github-api-version': '2022-11-28',
23	        ...(token ? { authorization: `Bearer ${token}` } : {}),
24	        'user-agent': 'claudinite-scheduler',
25	        ...(body ? { 'content-type': 'application/json' } : {}),
26	      },
27	      ...(body ? { body: JSON.stringify(body) } : {}),
28	    });
29	    let json = null;
30	    try { json = await res.json(); } catch { json = null; }
31	    return { status: res.status, json };
32	  };
33	}
34	
35	// The scheduler workflow's file name — the vendored shim's, identical in every
36	// member (the workflow is core, not pack content) and unchanged by the move to the
37	// work-item queue, which put the scheduler run at this same path. Named here rather than
38	// restated: the usage fold finds a repo's scheduler runs by it, to read their logs
39	// for the task-invocation records.
40	export const SCHEDULER_WORKFLOW_FILE = 'claudinite-scheduler.yml';
41	
42	// The executor workflow's file name, same contract: identical in every member,
43	// and the target of every `workflow_dispatch` in the queue's chain (DESIGN §10) —
44	// the close-time drain, a run's own re-dispatch, and the failure continuation.
45	export const EXECUTOR_WORKFLOW_FILE = 'claudinite-executor.yml';
46	
47	// The repo slug (owner/name) and default branch the workflow runs against, from
48	// the Actions environment. `GITHUB_REPOSITORY` is always set in a workflow;
49	// `GITHUB_REF_NAME` is the branch for a scheduled/dispatch run on the default branch.
50	export function actionRepoContext(env = process.env) {
51	  return {
52	    repo: env.GITHUB_REPOSITORY || null,
53	    defaultBranch: env.GITHUB_REF_NAME || 'main',
54	  };
55	}
